{
  "name": "buscar_pedido",
  "description": "Busca status e detalhes de um pedido no ERP. Use quando o usuário perguntar sobre prazo, situação ou itens de um pedido. NÃO use para criar ou cancelar pedidos.",
  "input_schema": {
    "type": "object",
    "properties": {
      "numero_pedido": {
        "type": "string",
        "description": "ID do pedido no formato BR-XXXXX. Ex: BR-12345"
      },
      "incluir_itens": {
        "type": "boolean",
        "description": "Se verdadeiro, retorna a lista de itens do pedido. Padrão: false."
      }
    },
    "required": ["numero_pedido"]
  }
}
